 void subjectAttendance(JSONObject schedule){base("Absensi Mata Pelajaran",true);card(store.subject(schedule),"Kelas "+store.className(schedule)+" • "+date(store.today().toString()),"check");run(()->j("pupils",store.students(store.className(schedule)),"logs",store.mapelLogs(schedule,store.today().toString(),store.today().toString())),data->{JSONObject d=(JSONObject)data;JSONArray pupils=a(d,"pupils");Map<String,String> states=new LinkedHashMap<>();String note="";for(JSONObject p:list(pupils))states.put(s(p,"id"),"hadir");for(JSONObject log:list(a(d,"logs")))if(s(log,"teaching_schedule_id").equals(s(schedule,"id"))){states.put(s(log,"student_id"),s(log,"status"));if(note.isEmpty())note=s(log,"notes");}attendanceEditor(pupils,states,true);LinearLayout c=card("Catatan / jurnal mengajar","Catatan disimpan bersama absensi pada jadwal ini.","card");EditText notes=input(this,"Materi, kegiatan atau catatan kelas",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);notes.setSingleLine(false);notes.setMinLines(3);notes.setText(note);c.addView(notes);Button save=button(this,"Simpan absensi & catatan",true,()->{if(saving)return;saving=true;Map<String,String> submitted=new LinkedHashMap<>(states);String journal=notes.getText().toString();run(()->{store.saveSubject(schedule,pupils,submitted,journal);return true;},r->{saving=false;toast("Absensi dan catatan berhasil disimpan");navigate("home");});});add(save);if(pupils.length()==0)save.setEnabled(false);});}
 void attendanceEditor(JSONArray pupils,Map<String,String> states,boolean defaults){LinearLayout holder=column(this);EditText search=input(this,"Cari nama atau NIS",InputType.TYPE_CLASS_TEXT);add(search);Runnable draw=()->{holder.removeAllViews();String query=search.getText().toString().toLowerCase(Locale.ROOT);for(JSONObject pupil:list(pupils)){if(!(s(pupil,"name")+s(pupil,"student_id")).toLowerCase(Locale.ROOT).contains(query))continue;LinearLayout c=Ui.card(this);pad(c,12);c.addView(text(this,s(pupil,"name"),14,INK,true));c.addView(text(this,s(pupil,"student_id")+" • "+s(pupil,"class"),10,MUTED,false));gap(c,7);LinearLayout buttons=row(this);for(String status:new String[]{"hadir","sakit","izin","alfa"}){Button b=button(this,status.equals("hadir")?"H":status.equals("sakit")?"S":status.equals("izin")?"I":"A",status.equals(states.get(s(pupil,"id"))),()->{});b.setContentDescription(s(pupil,"name")+": "+label(status));b.setTextColor(status.equals(states.get(s(pupil,"id")))?Color.WHITE:color(status));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(this,44),1);p.rightMargin=dp(this,5);buttons.addView(b,p);b.setOnClickListener(v->{states.put(s(pupil,"id"),status);((Runnable)holder.getTag()).run();});}c.addView(buttons);holder.addView(c);gap(holder,9);}};holder.setTag(draw);search.addTextChangedListener(watcher(draw));add(holder);draw.run();}
