 void manual(){base("Absensi Manual Wali Kelas",true);if(store.waliClasses().isEmpty()){empty("Anda belum ditugaskan sebagai wali kelas.");return;}classPicker(this::manual);if(selectedDay.isEmpty())selectedDay=store.today().toString();dateButton("Tanggal",selectedDay,value->{selectedDay=value;manual();});run(()->j("pupils",store.students(selectedClass),"logs",store.logs(selectedDay,selectedDay,"datang")),data->{JSONObject d=(JSONObject)data;JSONArray pupils=a(d,"pupils"),logs=a(d,"logs");Map<String,String> original=new LinkedHashMap<>(),states=new LinkedHashMap<>();Set<String> ids=new HashSet<>();for(JSONObject p:list(pupils))ids.add(s(p,"id"));for(JSONObject log:list(logs))if(ids.contains(s(log,"student_id"))){original.put(s(log,"student_id"),s(log,"status"));states.put(s(log,"student_id"),s(log,"status"));}attendanceEditor(pupils,states,false);Button save=button(this,"Simpan perubahan absensi",true,()->{if(saving)return;Map<String,String> changes=new LinkedHashMap<>();for(Map.Entry<String,String> e:states.entrySet())if(!e.getValue().equals(original.get(e.getKey())))changes.put(e.getKey(),e.getValue());if(changes.isEmpty()){toast("Belum ada perubahan");return;}new CardModal(this).setTitle("Simpan absensi?").setMessage(changes.size()+" perubahan • "+selectedClass+"\n"+date(selectedDay)).setPositiveButton("Simpan",(dialog,which)->{saving=true;run(()->{store.saveManual(selectedClass,selectedDay,pupils,changes,logs);return true;},r->{saving=false;toast("Absensi tersimpan");manual();});}).setNegativeButton("Batal",null).show();});add(save);});}
