 void attendanceStats(JSONArray pupils,JSONArray logs){Map<String,String> byStudent=new HashMap<>();for(JSONObject l:list(logs))byStudent.put(s(l,"student_id"),s(l,"status"));LinearLayout row=row(this);int count=0;for(String state:new String[]{"hadir","sakit","izin","alfa"}){int n=0;for(JSONObject p:list(pupils))if(state.equals(byStudent.get(s(p,"id"))))n++;LinearLayout box=column(this);pad(box,9);box.setBackground(surface(this,state.equals("hadir")?0xFFE0F9EC:state.equals("alfa")?0xFFFFE7EB:0xFFE7EDFF,16));box.addView(text(this,String.valueOf(n),23,color(state),true));box.addView(text(this,label(state),10,MUTED,true));LinearLayout.LayoutParams param=new LinearLayout.LayoutParams(0,-2,1);param.rightMargin=dp(this,5);row.addView(box,param);count+=n;}add(row);TextView summary=text(this,pupils.length()+" siswa • "+Math.max(0,pupils.length()-count)+" belum absen",12,MUTED,false);add(summary);}
